WITH inner_cte1 AS ( SELECT s.SCHOOL_NAME, c.DEPARTMENT_NAME, VARIANCE(c.CIP_PROGRAM_CODE) AS cip_code_variance FROM SIS_SUBJECT_CODE s JOIN SIS_COURSE_DESCRIPTION c ON s.SUBJECT_CODE = c.COURSE WHERE c.IS_DEGREE_GRANTING = 'Y' AND c.DEPARTMENT_NAME IS NOT NULL AND c.DEPARTMENT_NAME = 'Mathematics' GROUP BY s.SCHOOL_NAME, c.DEPARTMENT_NAME ), rollup_cte1 AS ( SELECT SCHOOL_NAME, DEPARTMENT_NAME, cip_code_variance FROM inner_cte1 UNION ALL SELECT s.SCHOOL_NAME, NULL AS DEPARTMENT_NAME, VARIANCE(c.CIP_PROGRAM_CODE) AS cip_code_variance FROM SIS_SUBJECT_CODE s JOIN SIS_COURSE_DESCRIPTION c ON s.SUBJECT_CODE = c.COURSE WHERE c.IS_DEGREE_GRANTING = 'Y' AND c.DEPARTMENT_NAME IS NOT NULL GROUP BY s.SCHOOL_NAME ), cte1_final AS ( SELECT SCHOOL_NAME, DEPARTMENT_NAME, cip_code_variance FROM rollup_cte1 ), inner_cte2 AS ( SELECT sd.SCHOOL_NAME, EXP(AVG(LOG(ccso.TOTAL_UNITS))) AS geometric_mean_total_units FROM COURSE_CATALOG_SUBJECT_OFFERED ccso JOIN SIS_DEPARTMENT sd ON ccso.DEPARTMENT_CODE = sd.DEPARTMENT_CODE WHERE ccso.TOTAL_UNITS > 0 AND ccso.IS_OFFERED_THIS_YEAR = 'Y' AND sd.IS_DEGREE_GRANTING = 'Y' AND ccso.DEPARTMENT_CODE <> '15' GROUP BY sd.SCHOOL_NAME ), cte2_final AS ( SELECT i.SCHOOL_NAME, i.geometric_mean_total_units, s.avg_geometric_mean, CASE WHEN i.geometric_mean_total_units > s.avg_geometric_mean * 1.05 THEN 'ABOVE_AVERAGE' WHEN i.geometric_mean_total_units < s.avg_geometric_mean * 0.95 THEN 'BELOW_AVERAGE' ELSE 'AVERAGE' END AS comparison_to_average FROM inner_cte2 i CROSS JOIN (SELECT AVG(geometric_mean_total_units) AS avg_geometric_mean FROM inner_cte2) s ) SELECT c1.SCHOOL_NAME, c1.DEPARTMENT_NAME, c1.cip_code_variance, c2.geometric_mean_total_units, c2.avg_geometric_mean, c2.comparison_to_average FROM cte1_final c1 JOIN cte2_final c2 ON c1.SCHOOL_NAME = c2.SCHOOL_NAME ORDER BY c1.SCHOOL_NAME, c1.DEPARTMENT_NAME